package com.ionixx.Event_Ticket_Booking.support;

import com.ionixx.Event_Ticket_Booking.dto.BookingRequest;
import com.ionixx.Event_Ticket_Booking.entity.Booking;
import com.ionixx.Event_Ticket_Booking.entity.Event;
import com.ionixx.Event_Ticket_Booking.entity.User;
import com.ionixx.Event_Ticket_Booking.enums.Category;
import com.ionixx.Event_Ticket_Booking.enums.Role;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Arrays;
import org.springframework.test.util.ReflectionTestUtils;

/** Builders for entities whose ids are generated by the database (no setId in production code). */
public final class TestData {

  private TestData() {}

  public static User user(Long id, String email, Role role) {
    User u = new User();
    u.setEmail(email);
    u.setPassword("hash");
    u.setRole(role);
    if (id != null) {
      ReflectionTestUtils.setField(u, "id", id);
    }
    return u;
  }

  public static Event event(
      Long id, int totalSeats, LocalDate date, String basePrice, Long organiserId) {
    Event e = new Event();
    e.setName("Event " + (id == null ? "new" : id));
    e.setCategory(Category.MUSIC);
    e.setBasePrice(new BigDecimal(basePrice));
    e.setTotalSeats(totalSeats);
    e.setEventDate(date);
    e.setVenue("Main Hall");
    e.setOrganiserId(organiserId);
    if (id != null) {
      ReflectionTestUtils.setField(e, "id", id);
    }
    return e;
  }

  public static Booking booking(Long id, Long eventId, Long userId, String status, int seats) {
    Booking b = new Booking();
    b.setEventId(eventId);
    b.setUserId(userId);
    b.setCustomerName("John Doe");
    b.setCustomerEmail("john@example.com");
    b.setSeats(seats);
    b.setStatus(status);
    b.setBookedOn(LocalDate.now());
    if (id != null) {
      ReflectionTestUtils.setField(b, "id", id);
    }
    return b;
  }

  public static BookingRequest bookingRequest(
      Long eventId, String name, String email, Integer... seats) {
    BookingRequest r = new BookingRequest();
    r.setEventId(eventId);
    r.setCustomerName(name);
    r.setCustomerEmail(email);
    r.setSeatNumbers(new ArrayList<>(Arrays.asList(seats)));
    return r;
  }
}
